window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f8536dca494f3f16"]={"versions": [{"id": "FIG-f8536dca494f3f16", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der statischen Schichtenarchitektur des AUTOSAR Network Management (NM) Stacks innerhalb der Classic Platform. Gezeigt wird die hierarchische Schichtung von der generischen NM-Koordination über busspezifische NM-Module bis hin zu den darunterliegenden Kommunikations- und Socket-Adapterschnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält neun Software-Module (<code>«module»</code>), strukturiert in drei vertikale Schichten:</p>\n<ul class=\"fig-list\"><li>Obere Schicht (generisch): <code>:Nm</code> (Network Management Interface).\n</li><li>Mittlere Schicht (busspezifisches Netzwerkmanagement): <code>:CanNm</code>, <code>:FrNm</code>, <code>LinNm::LinNm</code>, <code>UdpNm::UdpNm</code>.\n</li><li>Untere Schicht (Hardware-Abstraktions- und Transportschnittstellen): <code>:CanIf</code>, <code>:FrIf</code>, <code>LinIf::LinIf</code>, <code>SoAd::SoAd</code>.\n</li></ul>\n<p class=\"fig-p\">Die Module sind jeweils spaltenweise den entsprechenden Bussystemen zugeordnet: CAN (<code>:CanNm</code> über <code>:CanIf</code>), FlexRay (<code>:FrNm</code> über <code>:FrIf</code>), LIN (<code>LinNm::LinNm</code> über <code>LinIf::LinIf</code>) und Ethernet/IP (<code>UdpNm::UdpNm</code> über <code>SoAd::SoAd</code>). Schnittstellenbeziehungen sind implizit durch die vertikale Schichtung und Stapelung der Komponentenblöcke dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Schichtenarchitektur ohne Sequenzen, Kontrollflüsse oder Zustandsübergänge dar. Dynamische Abläufe und Nachrichtenflüsse werden nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die Integration des AUTOSAR NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Das Modul <code>:Nm</code> fungiert als zentrale, busunabhängige Abstraktionsschicht für die Anbindung an übergeordnete Schichten.\n</li><li>Unterhalb von <code>:Nm</code> müssen busspezifische NM-Module (<code>CanNm</code>, <code>FrNm</code>, <code>LinNm</code>, <code>UdpNm</code>) mit den jeweils korrespondierenden Interface- bzw. Adaptermodulen (<code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>, <code>SoAd</code>) gekoppelt werden.\n</li><li>Vertikale Abhängigkeiten und Kommunikationspfade folgen streng der Schichtung von <code>:Nm</code> über das jeweilige NM-Modul zur zugehörigen Bus-Schnittstelle.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-61d2240dec187f96", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der statischen Schichtenarchitektur des AUTOSAR Network Management (NM) Stacks inklusive Anbindung an den Communication Manager (ComM) innerhalb der Classic Platform. Gezeigt wird die hierarchische Schichtung vom übergeordneten Kommunikationsmanagement über das generische NM-Interface und busspezifische NM-Module bis zu den Schnittstellen- und Adaptermodulen der physikalischen Busse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält elf Software-Module (<code>«module»</code>), strukturiert in vier Schichten:</p>\n<ul class=\"fig-list\"><li>Oberste Schicht: <code>:ComM</code> (Communication Manager).\n</li><li>Zweite Schicht: <code>:Nm</code> (Network Management Interface).\n</li><li>Dritte Schicht (busspezifisches Netzwerkmanagement): <code>J1939Nm::J1939Nm</code>, <code>CanNm::CanNm</code>, <code>FrNm::FrNm</code>, <code>LinNm::LinNm</code>, <code>UdpNm::UdpNm</code>.\n</li><li>Vierte Schicht (Hardware-Abstraktions- und Transportschnittstellen): <code>CanIf::CanIf</code>, <code>FrIf::FrIf</code>, <code>LinIf::LinIf</code>, <code>SoAd::SoAd</code>.\n</li></ul>\n<p class=\"fig-p\">Das Modul <code>CanIf::CanIf</code> erstreckt sich über die Spalten von <code>J1939Nm::J1939Nm</code> und <code>CanNm::CanNm</code>. Die übrigen Zuordnungen verlaufen vertikal: <code>FrNm::FrNm</code> über <code>FrIf::FrIf</code>, <code>LinNm::LinNm</code> über <code>LinIf::LinIf</code>, <code>UdpNm::UdpNm</code> über <code>SoAd::SoAd</code>. Alle NM-Module sind unterhalb des gemeinsamen <code>:Nm</code>-Moduls angeordnet, welches seinerseits unter <code>:ComM</code> liegt. Interaktionsbeziehungen sind implizit durch Schichtung und Blockanordnung definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Schichtenarchitektur ohne Sequenzen, Kontrollflüsse oder Zustandsübergänge dar. Dynamische Abläufe und Nachrichtenflüsse werden nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die Integration des AUTOSAR NM-Stacks:</p>\n<ul class=\"fig-list\"><li>Der Communication Manager (<code>:ComM</code>) schließt den NM-Stack nach oben ab und steuert das generische <code>:Nm</code>.\n</li><li>Das Modul <code>:Nm</code> bindet busspezifische NM-Module an, darunter <code>CanNm</code>, <code>FrNm</code>, <code>LinNm</code>, <code>UdpNm</code> sowie <code>J1939Nm</code>.\n</li><li>Für die CAN-Kommunikation ist <code>CanIf::CanIf</code> als gemeinsame Schnittstelle für reguläres CAN-NM (<code>CanNm</code>) und J1939-Netzwerkmanagement (<code>J1939Nm</code>) vorzusehen.\n</li><li>Die FlexRay-, LIN- und Ethernet-Pfade koppeln <code>FrNm</code> an <code>FrIf</code>, <code>LinNm</code> an <code>LinIf</code> sowie <code>UdpNm</code> an <code>SoAd</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f8536dca494f3f16", "to": "FIG-61d2240dec187f96", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung des Moduls <code>«module» :ComM</code> oberhalb des Moduls <code>«module» :Nm</code>.\n</li><li>Ergänzung des Moduls <code>«module» J1939Nm::J1939Nm</code> auf der Schicht der busspezifischen NM-Module (unterhalb von <code>:Nm</code>, oberhalb von <code>CanIf::CanIf</code>).\n</li><li>Vereinheitlichung der Modul- und Instanzbezeichner:\n<ul class=\"fig-list\"><li><code>:CanNm</code> -&gt; <code>CanNm::CanNm</code>\n</li><li><code>:FrNm</code> -&gt; <code>FrNm::FrNm</code>\n</li><li><code>:CanIf</code> -&gt; <code>CanIf::CanIf</code>\n</li><li><code>:FrIf</code> -&gt; <code>FrIf::FrIf</code>\n</li></ul>\n</li><li>Erweiterung der Schnittstelle/Zuordnung von <code>CanIf::CanIf</code>, das nun unterhalb von <code>J1939Nm::J1939Nm</code> und <code>CanNm::CanNm</code> angeordnet ist.\n</li></ul>"}]};
